create table public.lesson_progress (id uuid primary key default gen_random_uuid(),member_id uuid not null references public.profiles(id) on delete cascade,lesson_slug text not null,started_at timestamptz not null default now(),read_sections jsonb not null default '[]'::jsonb check(jsonb_typeof(read_sections)='array'),pathway_answers jsonb not null default '{}'::jsonb check(jsonb_typeof(pathway_answers)='object'),knowledge_answers jsonb not null default '{}'::jsonb check(jsonb_typeof(knowledge_answers)='object'),knowledge_score integer not null default 0 check(knowledge_score between 0 and 100),knowledge_submitted boolean not null default false,completed_at timestamptz,updated_at timestamptz not null default now(),unique(member_id,lesson_slug),check(completed_at is null or(lesson_slug='digital-income-lesson-1' and knowledge_submitted and knowledge_score>=70)));
alter table public.lesson_progress enable row level security;
create policy "Members manage their own incomplete lesson progress" on public.lesson_progress for all to authenticated using(auth.uid()=member_id and completed_at is null) with check(auth.uid()=member_id and completed_at is null);
create policy "Members view their completed lesson progress" on public.lesson_progress for select to authenticated using(auth.uid()=member_id);
create or replace function public.complete_digital_income_lesson_one(pathway_responses jsonb,section_ids jsonb) returns void language plpgsql security definer set search_path=public as $$ declare required_sections constant text[]:=array['digital-income','getting-ready','freelancing','remote-employment','content-creation','digital-products','online-business','affiliate-marketing','dropshipping','drop-servicing','scam-awareness'];required_pathway constant text[]:=array['goal','strengths','pathway','customer','resources','safety'];computed_score integer;begin if auth.uid() is null then raise exception 'Authentication required';end if;if jsonb_typeof(section_ids)<>'array' or not(select bool_and(section_ids ? section_id) from unnest(required_sections)section_id)then raise exception 'Every lesson section must be read';end if;if jsonb_typeof(pathway_responses)<>'object' or not(select bool_and(length(trim(coalesce(pathway_responses->>question_id,'')))>0)from unnest(required_pathway)question_id)then raise exception 'Every pathway response is required';end if;select round(100.0*((knowledge_answers->>'meaning'='1')::integer+(knowledge_answers->>'freelance'='0')::integer+(knowledge_answers->>'remote'='2')::integer+(knowledge_answers->>'affiliate'='1')::integer+(knowledge_answers->>'delivery'='0')::integer+(knowledge_answers->>'scam'='2')::integer)/6)::integer into computed_score from public.lesson_progress where member_id=auth.uid() and lesson_slug='digital-income-lesson-1';if coalesce(computed_score,0)<70 then raise exception 'A verified score of at least 70 percent is required';end if;update public.lesson_progress set knowledge_score=computed_score,read_sections=section_ids,pathway_answers=pathway_responses,completed_at=now(),updated_at=now() where member_id=auth.uid() and lesson_slug='digital-income-lesson-1' and knowledge_submitted and completed_at is null;if not found then raise exception 'A submitted score of at least 70 percent is required';end if;end;$$;
revoke all on function public.complete_digital_income_lesson_one(jsonb,jsonb) from public;grant execute on function public.complete_digital_income_lesson_one(jsonb,jsonb) to authenticated;
comment on table public.lesson_progress is 'Member lesson progress only; certificate issue remains subject to all course requirements and authorised approval.';
